51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /**
70	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
71	     * forward to the next non-holiday business day, in the same way weekends are.
72	     */
73	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
74	        LocalDate.of(2026, 1, 1),
75	        LocalDate.of(2026, 1, 26),
76	        LocalDate.of(2026, 4, 25),
77	        LocalDate.of(2026, 12, 25),
78	        LocalDate.of(2026, 12, 28));
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper,
94	                                 AddressNormalizer addressNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.addressNormalizer = addressNormalizer;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        return createOwner(ownerFieldsDto);
131	    }
132	
133	    /**
134	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
135	     * response. The submitted fields are mapped to an {@link Owner}, which is
136	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
137	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
138	     * assigned its household} and screened for {@link #checkForConflicts(Owner, boolean) conflicts};
139	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
140	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
141	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
142	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
143	     * cannot be created.
144	     */
145	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	
148	        HttpStatus invalid = normalizeAndValidate(owner);
149	        if (invalid != null) {
150	            return new ResponseEntity<>(invalid);
151	        }
152	        if (isDailyLimitReached(owner.getRegistrationDate())) {
153	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
154	        }
155	
156	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
157	        assignHousehold(owner);
158	
159	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
160	        if (conflict != null) {
161	            return new ResponseEntity<>(conflict);
162	        }
163	
164	        assignDerivedAttributes(owner, sharesHousehold);
165	        this.clinicService.saveOwner(owner);
166	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
167	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
168	            owner.getMembershipLevel(), owner.getMembershipNumber());
169	        return created(owner);
170	    }
171	
172	    /**
173	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
174	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
175	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
176	     * postcode is checked against its city's region, a registration date in the future is rejected,
177	     * and the effective registration date (the supplied one, or today when none was given) is rolled
178	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
179	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
180	     * otherwise.
181	     */
182	    private HttpStatus normalizeAndValidate(Owner owner) {
183	        if (!normalizeAddress(owner)) {
184	            return HttpStatus.BAD_REQUEST;
185	        }
186	        String telephone = toE164(owner.getTelephone());
187	        if (telephone == null) {
188	            return HttpStatus.BAD_REQUEST;
189	        }
190	        owner.setTelephone(telephone);
191	        if (isDisposableEmail(owner.getEmail())) {
192	            return HttpStatus.BAD_REQUEST;
193	        }
194	        if (!owner.isPostcodeValid()) {
195	            return HttpStatus.BAD_REQUEST;
196	        }
197	        if (owner.getRegistrationDate() != null
198	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
199	            return HttpStatus.BAD_REQUEST;
200	        }
201	        LocalDate effectiveDate = owner.getRegistrationDate() != null
202	            ? owner.getRegistrationDate() : LocalDate.now();
203	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
204	        return null;
205	    }
206	
207	    /**
208	     * Normalize the owner's supplied address into its canonical stored form and report whether an
209	     * address was supplied at all. The owner may supply its address either as the structured
210	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
211	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
212	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
213	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
214	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
215	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
216	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
217	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
218	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
219	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
220	     * create must be rejected with {@code 400 Bad Request}.
221	     */
222	    private boolean normalizeAddress(Owner owner) {
223	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
224	        if (!line1.isEmpty()) {
225	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
226	            owner.setAddressLine1(line1);
227	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
228	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
229	            return true;
230	        }
231	        String address = addressNormalizer.normalize(owner.getAddress());
232	        if (address.isEmpty()) {
233	            return false;
234	        }
235	        owner.setAddressLine1(null);
236	        owner.setAddressLine2(null);
237	        owner.setAddress(address);
238	        return true;
239	    }
240	
241	    /**
242	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
243	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
244	     */
245	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
246	        "mailinator.com", "tempmail.com", "guerrillamail.com");
247	
248	    /**
249	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
250	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
251	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
252	     * against the blocklist.
253	     */
254	    private boolean isDisposableEmail(String email) {
255	        if (email == null || email.isEmpty()) {
256	            return false;
257	        }
258	        int at = email.lastIndexOf('@');
259	        if (at < 0) {
260	            return false;
261	        }
262	        String domain = email.substring(at + 1).toLowerCase();
263	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
264	    }
265	
266	    /**
267	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
268	     * deterministically from the owner's lastName and postcode, so every owner sharing that
269	     * lastName and postcode is assigned the same value automatically, independent of whether the
270	     * owner declares it shares a household. The link is assigned before the
271	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
272	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
273	     * size}.
274	     */
275	    private void assignHousehold(Owner owner) {
276	        owner.setHouseholdId(householdId(owner));
277	    }
278	
279	    /**
280	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
281	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
282	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
283	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
284	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
285	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
286	     * when the owner clashes with nothing and may be created.
287	     */
288	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
289	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
290	            return HttpStatus.CONFLICT;
291	        }
292	        if (isCityAtCapacity(owner.getCity())) {
293	            return HttpStatus.CONFLICT;
294	        }
295	        return null;
296	    }
297	
298	    /**
299	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
300	     * {@code Location} header pointing at {@code /api/owners/{id}}.
301	     */
302	    private ResponseEntity<OwnerDto> created(Owner owner) {
303	        HttpHeaders headers = new HttpHeaders();
304	        headers.setLocation(UriComponentsBuilder.newInstance()
305	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
306	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
307	    }
308	
309	    /**
310	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
311	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
312	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
313	     * householdSize}. Each is computed from the owner's own fields together with the owners already
314	     * present, so this runs after the owner has been validated and has passed the duplicate and
315	     * capacity checks, and immediately before it is persisted.
316	     */
317	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
318	        owner.setCustomerCode(customerCode(owner));
319	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
320	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
321	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
322	        assignPossibleDuplicate(owner, sharesHousehold);
323	    }
324	
325	    /**
326	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
327	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
328	     * so it is never flagged. Otherwise, because this runs after the hard
329	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
330	     * match; it is flagged only when it is a soft match of an existing owner as determined by
331	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
332	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
333	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
334	     */
335	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
336	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
337	        owner.setPossibleDuplicate(match != null);
338	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
339	    }
340	
341	    /**
342	     * The owners a newly created owner is checked against by the duplicate and identity rules:
343	     * the {@link #isHouseholdDuplicate(Owner) household-duplicate} and {@link #findSoftDuplicate(Owner)
344	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
345	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
346	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
347	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
348	     * soft delete retains but excludes from duplicate and identity detection.
349	     */
350	    private Collection<Owner> activeOwners() {
351	        return this.clinicService.findAllOwners().stream()
352	            .filter(owner -> !owner.isDeleted())
353	            .collect(Collectors.toList());
354	    }
355	
356	    /**
357	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
358	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
359	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
360	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
361	     * postcode never matches.
362	     */
363	    private Owner findSoftDuplicate(Owner owner) {
364	        if (owner.getPostcode() == null) {
365	            return null;
366	        }
367	        String candidateLastName = normalizeName(owner.getLastName());
368	        return activeOwners().stream()
369	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
370	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
371	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
372	            .min(Comparator.comparingInt(Owner::getId))
373	            .orElse(null);
374	    }
375	
376	    /**
377	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
378	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
379	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
380	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
381	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
382	     * every value built from the customer code (the membership number and its check digit) and the
383	     * owner's locality are derived from it.
384	     *
385	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
386	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
387	     * unique, and the de-duplicated code is returned.
388	     */
389	    private String customerCode(Owner owner) {
390	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
391	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
392	        String base = region + "-" + hash8;
393	
394	        Set<String> existingCodes = activeOwners().stream()
395	            .map(Owner::getCustomerCode)
396	            .filter(Objects::nonNull)
397	            .collect(Collectors.toSet());
398	
399	        if (!existingCodes.contains(base)) {
400	            return base;
401	        }
402	        int n = 2;
403	        while (existingCodes.contains(base + "-" + n)) {
404	            n++;
405	        }
406	        return base + "-" + n;
407	    }
408	
409	    /**
410	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
411	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
412	     * (business-day) registration date of the owner being created, so owners are counted per
413	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
414	     */
415	    private boolean isDailyLimitReached(LocalDate day) {
416	        long count = this.clinicService.findAllOwners().stream()
417	            .filter(existing -> day.equals(existing.getRegistrationDate()))
418	            .count();
419	        return count >= 100;
420	    }
421	
422	    /**
423	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
424	     * more than 80 owners have already been created for the given business day. Counts the owners
425	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
426	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
427	     * warning.
428	     */
429	    private boolean isBulkSignup(LocalDate day) {
430	        long count = this.clinicService.findAllOwners().stream()
431	            .filter(existing -> day.equals(existing.getRegistrationDate()))
432	            .count();
433	        return count > 80;
434	    }
435	
436	    /**
437	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
438	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
439	     * returned unchanged.
440	     */
441	    private LocalDate toBusinessDay(LocalDate date) {
442	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
443	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
444	            || PUBLIC_HOLIDAYS.contains(date)) {
445	            date = date.plusDays(1);
446	        }
447	        return date;
448	    }
449	
450	    /**
451	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
452	     * more owners. Cities are compared case-insensitively.
453	     */
454	    private boolean isCityAtCapacity(String city) {
455	        long count = this.clinicService.findAllOwners().stream()
456	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
457	            .count();
458	        return count >= 50;
459	    }
460	
461	    /**
462	     * The number of existing owners that already share the given firstName and lastName,
463	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
464	     * whitespace runs collapsed). Counted over the owners present before this create.
465	     */
466	    private int namesakeCount(String firstName, String lastName) {
467	        String candidateFirstName = normalizeName(firstName);
468	        String candidateLastName = normalizeName(lastName);
469	        return (int) activeOwners().stream()
470	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
471	                && normalizeName(existing.getLastName()).equals(candidateLastName))
472	            .count();
473	    }
474	
475	    /**
476	     * The number of members in this owner's household after this create: the count of existing
477	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
478	     * created. An owner with no household ({@code householdId == null}) is a household of one.
479	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
480	     * does not depend on the order in which household members were created.
481	     */
482	    private int householdSize(String householdId) {
483	        if (householdId == null) {
484	            return 1;
485	        }
486	        long existing = this.clinicService.findAllOwners().stream()
487	            .filter(other -> householdId.equals(other.getHouseholdId()))
488	            .count();
489	        return (int) existing + 1;
490	    }
491	
492	    /**
493	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
494	     * cannot form a valid E.164 number.
495	     *
496	     * <p>A leading '+' and country code are kept when present; otherwise country code
497	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
498	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
499	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
500	     * exactly the national-digit count that code requires (see
501	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
502	     */
503	    private String toE164(String telephone) {
504	        if (telephone == null) {
505	            return null;
506	        }
507	        boolean hasCountryCode = telephone.trim().startsWith("+");
508	        String digits = telephone.replaceAll("\\D", "");
509	        String e164;
510	        if (hasCountryCode) {
511	            e164 = digits;
512	        } else {
513	            if (digits.startsWith("0")) {
514	                digits = digits.substring(1);
515	            }
516	            e164 = "61" + digits;
517	        }
518	        if (e164.length() < 8 || e164.length() > 15) {
519	            return null;
520	        }
521	        if (!Owner.hasValidNationalLength(e164)) {
522	            return null;
523	        }
524	        return "+" + e164;
525	    }
526	
527	    /**
528	     * Whether the candidate owner belongs to a household that already exists, and so must be
529	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
530	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
531	     * and postcode), so any existing owner carrying the same householdId means this owner is a
532	     * second member of an already-registered household. Two owners sharing a lastName and postcode
533	     * are therefore the same household: the second is a household duplicate.
534	     */
535	    private boolean isHouseholdDuplicate(Owner owner) {
536	        String householdId = owner.getHouseholdId();
537	        if (householdId == null) {
538	            return false;
539	        }
540	        return activeOwners().stream()
541	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
542	    }
543	
544	    /**
545	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
546	     * to a single space and lower-case. A null value normalizes to the empty string.
547	     */
548	    private String normalizeName(String value) {
549	        if (value == null) {
550	            return "";
551	        }
552	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
553	    }
554	
555	    /**
556	     * A stable shared identifier for the household an owner belongs to, derived deterministically
557	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
558	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
559	     * assigned the same value regardless of the order in which they are created. Formatted as the
560	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
561	     * (an absent postcode contributes the empty string).
562	     */
563	    private String householdId(Owner owner) {
564	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
565	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
566	        return shaHexUpper(key).substring(0, 12);
567	    }
568	
569	    /**
570	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
571	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
572	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
573	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
574	     * {@link #customerCode} keeps the first 8).
575	     */
576	    private String shaHexUpper(String input) {
577	        try {
578	            byte[] digest = MessageDigest.getInstance("SHA-256")
579	                .digest(input.getBytes(StandardCharsets.UTF_8));
580	            StringBuilder sb = new StringBuilder(digest.length * 2);
581	            for (byte b : digest) {
582	                sb.append(String.format("%02x", b));
583	            }
584	            return sb.toString().toUpperCase();
585	        }
586	        catch (NoSuchAlgorithmException e) {
587	            throw new IllegalStateException("SHA-256 not available", e);
588	        }
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Override
593	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
594	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
595	        if (currentOwner == null) {
596	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
597	        }
598	        currentOwner.setAddress(ownerFieldsDto.getAddress());
599	        currentOwner.setCity(ownerFieldsDto.getCity());
600	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
601	        currentOwner.setLastName(ownerFieldsDto.getLastName());
602	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
603	        this.clinicService.saveOwner(currentOwner);
604	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
605	    }
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Transactional
609	    @Override
610	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
611	        Owner owner = this.clinicService.findOwnerById(ownerId);
612	        if (owner == null) {
613	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
614	        }
615	        this.clinicService.deleteOwner(owner);
616	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
617	    }
618	
619	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
620	    @Override
621	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
622	        Owner owner = this.clinicService.findOwnerById(ownerId);
623	        if (owner == null) {
624	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
625	        }
626	        HttpHeaders headers = new HttpHeaders();
627	        Pet pet = petMapper.toPet(petFieldsDto);
628	        owner.setId(ownerId);
629	        pet.setOwner(owner);
630	        pet.getType().setName(null);
631	        this.clinicService.savePet(pet);
632	        PetDto petDto = petMapper.toPetDto(pet);
633	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
634	            .buildAndExpand(pet.getId()).toUri());
635	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
636	    }
637	
638	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
639	    @Override
640	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
641	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
642	        if (currentOwner != null) {
643	            Pet currentPet = this.clinicService.findPetById(petId);
644	            if (currentPet != null) {
645	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
646	                currentPet.setName(petFieldsDto.getName());
647	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
648	                this.clinicService.savePet(currentPet);
649	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
650	            }
651	        }
652	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
653	    }
654	
655	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
656	    @Override
657	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
658	        HttpHeaders headers = new HttpHeaders();
659	        Visit visit = visitMapper.toVisit(visitFieldsDto);
660	        Pet pet = new Pet();
661	        pet.setId(petId);
662	        visit.setPet(pet);
663	        this.clinicService.saveVisit(visit);
664	        VisitDto visitDto = visitMapper.toVisitDto(visit);
665	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
666	            .buildAndExpand(visit.getId()).toUri());
667	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
668	    }
669	
670	
671	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
672	    @Override
673	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
674	        Owner owner = this.clinicService.findOwnerById(ownerId);
675	        if (owner != null) {
676	            Pet pet = owner.getPet(petId);
677	            if (pet != null) {
678	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
679	            }
680	        }
681	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
682	    }
683	}
